CAT_DEEPDIVE = {
    'buldozery': [
        ('Тяговый класс и отвал: что решает, а не только тонны техники', 'Тяговый класс не равен массе машины, но связан с ней: чем выше класс, тем больше усилие бульдозер передаёт на грунт через гусеницы. Ключевая рабочая характеристика — усилие подпора отвала: способность заглубляться и резать грунт под нагрузкой. Она зависит не только от мощности двигателя, но и от давления в гидросистеме и диаметра гидроцилиндров, которые двигают отвал. Поэтому две машины схожей массы могут по-разному вести себя на плотном суглинке или мёрзлом грунте — разница в гидравлике, а не только в лошадиных силах. Отдельный параметр — форма отвала. Прямой отвал точнее держит профиль при чистовой планировке и увереннее работает на твёрдых и каменистых грунтах; полусферический и поворотный отвал увеличивает объём материала за проход и выгоднее при перемещении рыхлого грунта на расстояние. На плотных, мёрзлых или каменистых грунтах отдельно нужен задний рыхлитель — без него тяжёлая машина будет буксовать вместо того, чтобы резать. Это стоит уточнять при заявке, а не по факту приезда техники на объект.'),
        ('Проходимость гусеничного хода и логистика подачи на объект', 'Гусеничный ход распределяет вес машины на большую площадь опоры и создаёт удельное давление на грунт в разы ниже, чем у колёсной техники сопоставимого класса — поэтому бульдозер уверенно работает на слабых, переувлажнённых и рыхлых грунтах, где колёсная машина буксует или проваливается, и не разрушает существующее покрытие так, как колёсная техника. Обратная сторона той же ходовой части — бульдозер не может своим ходом передвигаться по дорогам общего пользования: его завозят и увозят на трале. Это отдельная статья расходов и отдельный логистический этап, который заказчики часто недооценивают: нужен подъезд для трала, место для разгрузки и разворота, включая манёвр отвалом на самой площадке, а на закрытой территории — согласованный въезд и пропуск. Если площадка стеснена или доступ ограничен по габаритам, это стоит проговорить на этапе заявки — иначе смена начнётся с простоя на разгрузке, а не с работы.'),
        ('Из чего складывается цена и сроки', 'Стоимость смены складывается из класса и мощности машины, доставки тралом (зависит от расстояния и габаритов техники) и характера грунта — на плотном, каменистом или мёрзлом грунте скорость резания ниже, и тот же объём работ занимает больше смен, чем на рыхлом грунте той же площади. Сезонность работает в обе стороны: зимой на мёрзлых грунтах чаще нужен более тяжёлый класс с рыхлителем, а весной и летом — пиковый спрос на технику из-за старта строительного сезона, что напрямую влияет на доступность машин и сроки подачи. Частая ошибка заказчиков — выбирать самый лёгкий и дешёвый класс без учёта реального объёма и плотности грунта: машина отработает смену, но не выполнит объём, и придётся либо продлевать аренду, либо доплачивать за более тяжёлый класс на следующий день. Вторая типичная ошибка — не сообщать заранее особенности подъезда и площадки: если трал не может подойти вплотную, перегон своим ходом на последнем участке или дополнительная техника для разгрузки увеличивают итоговую стоимость, которую проще обсудить заранее, чем выяснять на объекте.'),
    ],
    'avtogreidery': [
        ('Как выбрать класс автогрейдера под задачу', 'Автогрейдеры условно делят на классы по массе и мощности двигателя — лёгкие (порядка 9–10 тонн), средние (10–13 тонн) и тяжёлые (от 13 тонн и выше), и вместе с классом растёт длина и жёсткость отвала, а значит и усилие резания грунта. Для содержания грунтовых дорог, подсыпки обочин и мелкого ямочного ремонта обычно хватает лёгкого или среднего класса — такие машины манёвреннее и дешевле в почасовой эксплуатации. Для профилирования проезжей части под асфальтирование, планировки крупных строительных площадок, устройства откосов и работы с плотным или частично промёрзшим грунтом нужен средний или тяжёлый класс с запасом мощности, часто вместе с навесным оборудованием — кирковщиком (рыхлителем) для твёрдого грунта или откосником для формирования уклонов кюветов. Отдельно стоит учитывать колёсную формулу: трёхосные машины с шарнирно-сочленённой рамой точнее держат заданный уклон и разворачиваются на меньшей площади, что важно на стеснённых объектах.'),
        ('Эксплуатационные нюансы: отвал, рама и сезон', 'Рабочий орган автогрейдера — отвал на поворотном круге: его выставляют под углом к направлению движения, наклоняют и выносят в сторону от продольной оси машины, что и позволяет сформировать профиль дороги, кювет или откос за один-два прохода вместо ручной доводки. Шарнирно-сочленённая рама даёт машине заходить в повороты с меньшим радиусом, но требует достаточно плотной опорной поверхности — на переувлажнённом, раскисшем грунте колёсная техника буксует и оставляет колею, поэтому профилирование сразу после дождя или в период активного таяния снега обычно малоэффективно, и такие работы разумнее переносить на более сухую погоду. Работа с уплотнённым или промёрзшим грунтом требует либо более тяжёлого класса машины, либо предварительного рыхления навесным кирковщиком: попытка резать мёрзлый грунт лёгким отвалом ведёт к ускоренному износу режущих кромок и кратно большему числу проходов.'),
        ('Из чего складывается цена и типичные ошибки заказа', 'Стоимость работы автогрейдера складывается из нескольких статей: почасовой или посменной ставки, которая растёт вместе с классом машины; стоимости подачи техники на объект — часть автогрейдеров может дойти своим ходом на разрешённое расстояние, часть требует перевозки на трале, что добавляет отдельную статью расходов и время на объект; и минимального объёма заказа, который у большинства подрядчиков считается сменами или часами, а не отдельными проходами. Частая ошибка заказчика — взять машину лёгкого класса под объём и тип грунта, который по факту требует среднего или тяжёлого, из-за более низкой ставки: в итоге объект проходят в несколько раз больше раз, чем закладывалось, и итоговые сроки и стоимость превышают вариант с изначально верно подобранной техникой. Вторая типичная ошибка — не уточнить заранее способ подачи техники и состояние подъездных путей: если автогрейдер нельзя завести своим ходом, а трал не проходит по узкой или размытой дороге, старт работ срывается уже в первый день.'),
    ],
    'dorozhnye-katki': [
        ('Как выбрать класс и тип катка под объект', 'Катки условно делят по массе на лёгкие (до 6 т), средние (6–10 т) и тяжёлые (от 10 т) — эта градация закрепилась в отраслевой практике: с ростом массы растёт и нагрузка, которую валец передаёт на слой, а значит и толщина материала, которую каток продавливает за проход. Дальше выбор идёт по двум осям. Первая — вибрация или статика: вибрационный каток уплотняет не только весом, но и колебаниями вальца, поэтому его берут под грунт, песок и щебень, где материал нужно «просадить» на глубину; статический работает мягче, и его предпочитают там, где вибрация нежелательна — рядом с фундаментами и подземными коммуникациями. Вторая ось — форма вальца: кулачковый (падфут) эффективен на связных грунтах — суглинке, глине, — кулачки пробивают верхний слой и уплотняют изнутри; гладкий валец нужен на сыпучих материалах и на финишных проходах, включая асфальт. Итоговое правило простое: чем толще укладываемый слой, тем тяжелее должен быть каток и выше амплитуда вибрации — лёгкая машина на толстом слое «плавает» по поверхности, не давая уплотнения по глубине.'),
        ('Асфальт: почему решает не каток, а тайминг подачи', 'При укатке асфальтобетона у катка гораздо меньше степеней свободы, чем на грунте — здесь решает не столько модель машины, сколько попадание в температурное окно. Уплотнение начинают, пока смесь ещё не остыла от температуры укладки — обычно это диапазон около 120–140°C; раньше начинать нельзя, каток просто «топит» ещё жидкую смесь. Нижняя граница — примерно 80–90°C: ниже неё битум начинает кристаллизоваться, и проход катка уже не уплотняет слой, а ломает его структуру. Отсюда практический вывод для логистики подачи: каток должен стоять на площадке готовым к работе до того, как приедет асфальтобетон, а не вызываться постфактум после разгрузки — на ветру и в прохладную погоду смесь теряет температуру быстрее, чем кажется на глаз, и рабочее окно закрывается раньше расчётного. Типичная ошибка заказчика — заказывать каток и асфальтобетоновоз одним звонком без разницы во времени выезда: тогда каток технически ещё «в пути», пока привезённый асфальт уже остывает на объекте, и часть уложенного полотна приходится переукладывать.'),
        ('Из чего складывается цена и срок подачи', 'Стоимость подачи катка не сводится к «цене за час» — это стоит проговорить на этапе заявки, а не постфактум. Класс машины: тяжёлый вибрационный каток дороже в подаче, чем лёгкий статический, потому что для перевозки чаще нужен трал, а не обычная площадка. Логистика — цена растёт не только от километража, но и от того, разрешён ли маршрут для негабаритной техники и нужно ли согласование проезда. Срок — почасовая ставка отличается от суточной и тем более от ставки на весь объём работ; для многодневного объекта выгоднее сразу фиксировать посуточную или проектную схему, а не продлевать день за днём. Сезонность — дорожно-строительный сезон компактный (весна–осень), в его разгар свободная машина на конкретную дату — вопрос заблаговременной брони, а не данность; в межсезонье договориться обычно проще и дешевле. Отдельная статья расходов — простой по вине площадки: если каток подан, а фронт работ не готов (не завезён асфальт, участок не размечен), время простоя чаще всего оплачивается отдельно, и это стоит уточнять заранее, а не выяснять по факту.'),
    ],
    'frontalnye-pogruzchiki': [
        ('Как подобрать класс погрузчика и объём ковша под задачу', 'Погрузчики условно делятся на лёгкий класс (грузоподъёмность примерно до 2 т — склады, крытые площадки, стеснённые проезды), средний (2–5 т — основной рабочий класс на стройплощадках, при погрузке ПГС и щебня, в дорожном строительстве) и тяжёлый (от 5 т — карьеры, плотные породы, постоянная работа в связке с самосвалами). Но подбор только по паспортной грузоподъёмности не всегда верен: реальная нагрузка на ковш зависит от плотности материала, а не только от его объёма. Влажный песок весит около 1,8 т/м³, и ковш объёмом 3 м³ с таким песком даёт почти 5,4 т фактической массы — для этого нужна машина от 5 т, иначе техника работает на пределе и быстрее изнашивается. С лёгкими материалами — углём, снегом, зерном — логика обратная: выгоднее брать ковш большего объёма при той же грузоподъёмности, а под щебень и мокрый грунт, наоборот, ставят ковш меньше, потому что масса набирается быстрее объёма. Поэтому в заявке важно указывать не просто «нужен погрузчик», а материал и его состояние — сухой, влажный, мёрзлый: от этого зависит, какую именно модель и ковш имеет смысл подавать на объект.'),
        ('Логистика подачи: доступ на площадку и сезонность', 'При заказе стоит заранее сообщить состояние подъездных путей: ширину проезда, наличие разворота, тип покрытия. Грунтовая площадка после дождя или в распутицу может не выдержать многотонную технику — если предупредить об этом заранее, подадут модель с меньшим давлением на грунт, если нет — подача срывается уже на месте. Компактные модели обычно доставляют своим ходом на короткие расстояния, тяжёлые — тралом на низкорамном прицепе, это увеличивает и срок, и стоимость логистики. Отдельная сезонная особенность — зима: спрос на уборку и погрузку снега резко растёт, и та же техника, что летом работает на стройке, уходит под коммунальные заказы, поэтому зимнюю заявку стоит подавать заранее, не рассчитывая на подачу день в день. Частая ошибка заказчика — заявка «на глазок», без указания материала, расстояния подвоза и состояния площадки: в итоге на объект приезжает техника не того класса, и время уходит на замену.'),
        ('Из чего складывается цена и срок подачи', 'Стоимость складывается из нескольких частей, и разброс цен на рынке объясняется именно ими, а не произвольной наценкой. Основа — класс техники и объём ковша: выше грузоподъёмность и объём — выше базовая ставка за смену или час. Дальше — доставка: для тяжёлых моделей это трал, а при негабаритных габаритах ещё и оформление сопровождения, что добавляет и время, и деньги. Отдельно считается топливо — оно либо включено в ставку, либо оплачивается заказчиком по факту расхода, это нужно уточнять на этапе заявки, а не постфактум. Простой техники по вине заказчика — неготовая площадка, нет фронта работ, задержка с документами на объект — как правило, оплачивается отдельно от рабочего времени. Срок подачи зависит не только от расстояния до объекта, но и от загрузки техники нужного класса на конкретную дату: в пиковые периоды — строительный сезон, зимняя уборка снега — свободную машину нужного класса нужно бронировать заранее.'),
    ],
    'teleskopicheskie-pogruzchiki': [
        ('Как выбирать модель: высота, грузоподъёмность и вылет, а не просто «телескопический погрузчик»', 'Заявка «нужен телескопический погрузчик» без параметров — это заявка вслепую. У этого класса техники грузоподъёмность и высота подъёма взаимозависимы: чем выше поднята стрела и чем дальше она выдвинута вперёд, тем меньше вес, который машина может держать на этой высоте безопасно. Диапазон моделей на рынке большой: в модельном ряду JCB Loadall — 14 машин с грузоподъёмностью до 4,1 тонны и высотой подъёма от 4 до 14 метров, а у более высотных моделей, например Manitou MT-X 1840, стрела поднимает груз до 18 метров при грузоподъёмности около 4 тонн. Поэтому при подборе техники нужно назвать три конкретных числа: максимальную высоту, на которую нужно поднять груз, его вес и вылет стрелы — насколько далеко нужно подать груз вперёд или в сторону (на стеллаж, через оконный или дверной проём, за парапет здания). Четвёртый параметр — навесное оборудование: вилы для паллет, ковш, крюк, монтажная стрела, поворотный ковш. Под задачу подбирается связка «машина + навеска», а не абстрактная единица техники.'),
        ('Почему телескопический погрузчик, а не фронтальный', 'Разница не только в стреле. У фронтального погрузчика рама шарнирно-сочленённая — она переламывается пополам при повороте, у телескопического рама цельная, а поворот идёт за счёт колёс, как у обычного автомобиля. Из этого вытекает главное практическое отличие: телескопическая стрела выдвигается вперёд и позволяет подать груз вглубь — на верхний ярус стеллажа, в дверной проём, за пределы контура здания — без того, чтобы подгонять саму машину вплотную к точке выгрузки. Это решающее преимущество на стеснённых площадках: в плотной застройке, во дворах, на объектах с узким подъездом, где фронтальному погрузчику просто некуда развернуться. Обратная сторона конструкции — при выдвинутой стреле с грузом на высоте машине нужна ровная и несущая площадка под опорами; если грунт не утрамбован, участок с уклоном или площадка не подготовлена, это стоит обсудить на этапе заявки, а не выяснять по факту прибытия техники на объект.'),
        ('Типичные ошибки заказчиков и из чего складывается цена', 'Самая частая ошибка — заявка без параметров: «нужен телескопический погрузчик на объект» без высоты подъёма, веса груза и требуемого вылета стрелы. В итоге на площадку иногда приезжает машина не того класса, и её приходится менять — это теряет время и деньги для обеих сторон. Вторая ошибка — не учитывать логистику подачи: часть телескопических погрузчиков может доехать до объекта своим ходом, часть по массе и габаритам требует трала, а это отдельная статья расходов и времени, которую нужно закладывать в срок подачи техники заранее, а не в день начала работ. Экономика аренды складывается из класса машины (чем выше высота подъёма и грузоподъёмность — тем дороже смена или сутки), длительности работ, способа доставки (своим ходом или тралом) и навесного оборудования, если оно нестандартное. Сезонность тоже влияет напрямую: в межсезонье и зимой доставка на объекты с грунтовыми подъездными путями может занимать больше времени и требовать более внимательного планирования даты подачи.'),
    ],
    'mini-pogruzchiki': [
        ('Как выбрать класс мини-погрузчика под задачу', 'Мощность двигателя — не главный параметр выбора. Определяющих на практике два: грузоподъёмность и ширина машины относительно точек проезда на объекте. Модели нижнего класса, в районе 400 кг, обычно берут не потому, что материала мало, а потому, что он плотный — ПГС, цемент, готовый бетонный раствор: здесь важна именно грузоподъёмность ковша, а не его объём. Более тяжёлые классы, ориентировочно 700–1600 кг, чаще работают на стройплощадках и в коммунальном хозяйстве, где за смену чередуются грунт, снег, паллеты и строительный бой — универсальность важнее пиковой грузоподъёмности.\n\nВторой критерий, который часто упускают на этапе заявки, — реальная ширина проезда: ворота, дверные проёмы, лифтовые холлы, промежутки между стеллажами. На рынке есть узкорамные версии мини-погрузчиков, спроектированные под стандартные дверные проёмы и другие стеснённые проходы — это отдельный параметр модели, который стоит уточнять под конкретный объект до подачи техники, а не после.\n\nТретий критерий — совместимость навесного оборудования. Мини-погрузчик — это, по сути, базовая машина с быстросъёмным замком; ковш, вилы, гидромолот, щётка или отвал подбираются под задачу и должны подходить именно к той модели, что приедет на объект. Поэтому в заявке лучше описывать саму задачу — «вывезти грунт», «расчистить площадку от снега», «поднять паллеты на этаж», — а не просто «нужен мини-погрузчик»: так проще подобрать в партнёрской сети и машину, и навеску под неё.'),
        ('Колёсный или гусеничный: что решает выбор', 'Разница между колёсной и гусеничной базой — не про эстетику, а про давление на грунт и сцепление. У гусеничных моделей за счёт увеличенной площади контакта ниже давление на грунт и лучше держащая способность на рыхлых, влажных и сыпучих поверхностях, они устойчивее на уклонах — поэтому на раскисшем грунте, стройплощадке без твёрдого покрытия или зимой на снегу и льду гусеничная база обычно предпочтительнее. Колёсные модели, наоборот, манёвреннее и быстрее передвигаются по твёрдому покрытию — асфальту, бетону, плитке — и меньше повреждают финишное покрытие там, где оно уже уложено, что важно на объектах с благоустройством или в помещениях.\n\nДля зимней эксплуатации колёсной техники есть промежуточный вариант — шины с ошиповкой или цепи противоскольжения, но по проходимости на снегу гусеничная база всё равно остаётся вне конкуренции. Вывод для заявки простой: тип ходовой части стоит называть исходя не из личных предпочтений, а из реального состояния площадки на дату работ — твёрдое покрытие или грунт/снег, — и уточнять это до подачи техники.'),
        ('Из чего складывается цена и типичные ошибки в заявке', 'Стоимость подачи мини-погрузчика обычно складывается из нескольких частей: машино-часы работы, доставка техники до объекта и обратно (зависит от расстояния и доступности площадки), минимальный оплачиваемый период заказа и отдельно — навесное оборудование, если оно не входит в комплект базовой модели. Точные цифры без конкретного объекта называть бессмысленно — они зависят от класса машины, района, срочности и набора навески, но структура сметы всегда примерно такая.\n\nИз ошибок заказчиков повторяются две. Первая — заявку формулируют как «нужен мини-погрузчик» без описания задачи и без замера габаритов проезда, из-за чего на объект может приехать техника, которая физически не проходит в нужный проём или не тянет материал по грузоподъёмности. Вторая — заявку подают день в день, особенно в пиковые периоды (первый снег зимой, начало стройсезона весной), когда свободная техника нужного класса в проверенной сети разбирается быстрее всего. Обе ошибки закрываются одинаково: заранее описать задачу, габариты объекта и желаемую дату — а класс и тип ходовой части подобрать уже под эти вводные.'),
    ],
    'avtobetononasosy': [
        ('Как подобрать вылет стрелы и класс насоса под объект', 'Главный параметр подбора — не этажность здания, а реальное расстояние от точки, где насос сможет встать с раскрытыми опорами, до самой дальней и высокой точки заливки. У серийных автобетононасосов вылет стрелы растёт по классам: от машин компактного класса с вылетом порядка 20 м до крупных установок со стрелой более 50 м на многоосном шасси. На конце стрелы обычно закрепляют гибкий рукав длиной до нескольких метров — он даёт точную подводку бетона в стеснённых местах без перестановки машины. На практике геометрия площадки — узкий проезд, плотная застройка, деревья или провода — ограничивает выбор чаще, чем высота этажей: короткая стрела с удобной точкой стоянки нередко перекрывает заливку лучше, чем длинная, которую негде раскрыть. Второй параметр подбора — производительность в м³/ч: её соотносят с темпом подвоза бетона миксерами и объёмом, который нужно уложить, пока смесь ещё сохраняет подвижность.'),
        ('Требования к бетонной смеси и площадке', 'Через стрелу и бетоновод проходит не любая смесь. Для нормальной прокачки бетон должен иметь повышенную подвижность — на практике это марки не ниже П3, а многие подрядчики работают только с П4: жёсткие смеси П1–П2, рассчитанные на укладку с ручным вибрированием, в насос не годятся и рискуют застрять в трубе. Крупность заполнителя тоже должна быть согласована с диаметром бетоновода — избыточно крупный щебень, начавший схватываться или расслоившийся бетон, случайный мусор в смеси — частые причины пробки, из-за которой останавливается вся заливка. Со стороны площадки важны: устойчивое ровное основание под выносные опоры (они держат вес машины и стрелы в раскрытом положении, и просадка грунта под одной опорой — причина аварийной остановки), отсутствие проводов и веток в зоне работы стрелы, подъезд, достаточный для машины в транспортном положении. Эти моменты разумно проверять на этапе согласования, а не в день заливки.'),
        ('Из чего складывается цена и срок подачи', 'Стоимость работы автобетононасоса обычно складывается не только из объёма перекачанного бетона. В расчёт входят: подача машины на объект и обратно, минимальный оплачиваемый блок времени (насос заказывают не на 20 минут, а на определённый минимум часов — обычная практика у большинства подрядчиков), класс машины — более длинная стрела и мощная установка стоят дороже часа работы компактной, дополнительные метры инвентарного трубопровода или рукава при нестандартной геометрии подачи, и промывка системы после окончания заливки. Отдельная статья расходов — простой: если миксеры с бетоном подходят с перерывами, насос стоит, и это время обычно тоже оплачивается, а в жаркую погоду пауза в подаче грозит схватыванием смеси прямо в бетоноводе. Поэтому синхронизация графика бетонного завода и насоса — не техническая мелочь, а прямой фактор итоговой цены и срока работ.'),
    ],
    'avtobetonosmesiteli': [
        ('Объём барабана и шасси: от чего реально зависит выбор', 'Ошибка чаще всего не в самом миксере, а в оценке подъездных путей. Разница в цене между 6- и 7-кубовыми моделями почти не ощущается: барабаны такого объёма ставят на одно и то же шасси, поэтому если участок позволяет манёвр, разумнее сразу заказывать 7 м³ — переплата минимальна, а число рейсов меньше. 8-кубовые машины на рынке — редкость: они проигрывают по цене и доступности 9-кубовым, которые фактически стали стандартом «крупного» миксера. Дальше вопрос не в кубатуре, а в том, пройдёт ли гружёная машина на объект. Полностью загруженный 9-кубовый барабан — это ощутимая масса на оси, и то, как она распределена, зависит от колёсной формулы: у шасси 8х4 нагрузка ложится на четыре оси вместо трёх, что имеет значение на старых внутриквартальных дорогах, мостах и переездах с ограничением по осевой нагрузке, а также на тесных площадках, где четырёхосной машине попросту негде развернуться. Поэтому для точечной застройки в плотной старой застройке часто выгоднее взять машину меньшего объёма и сделать лишний рейс, чем рисковать проездом крупногабаритной техники.'),
        ('Почему барабан не должен останавливаться в пути', 'Пока смесь едет к объекту, барабан обязан медленно вращаться — иначе крупный заполнитель начинает расслаиваться и оседать на дно, и на выходе получается неоднородный бетон. Привод барабана делают либо от двигателя шасси через коробку отбора мощности, либо от отдельного автономного двигателя — второй вариант не зависит от режима работы основного двигателя и надёжнее держит вращение на стоянках и в пробках. Отсюда же и требование к маршруту: ГОСТ 7473 отдельным приложением нормирует предельно допустимую продолжительность транспортирования готовой бетонной смеси, и норматив зависит от температуры воздуха и температуры самой смеси — чем жарче, тем меньше запас времени до начала схватывания. На практике это значит, что при заказе важно называть не район, а точный адрес и реальное окно доставки: пробки на маршруте — не мелочь, а фактор, из-за которого может понадобиться либо замедлитель схватывания в составе смеси (это решение завода-изготовителя, а не перевозчика), либо выбор другого завода-отгрузчика, который окажется физически ближе к объекту.'),
        ('Сезонные нюансы и из чего складывается цена', 'Зимой к обычным требованиям добавляется температурный контроль: смесь не должна остыть и потерять подвижность за время в пути, поэтому в холодный период чаще используют утеплённые барабаны и трубопроводы, а оборачиваемость машины рассчитывают так, чтобы разгрузка прошла до того, как бетон подойдёт к границе рабочей консистенции. После каждой выгрузки барабан промывают водой: если этого не делать, внутри нарастает слой окаменевшего бетона, который со временем заметно съедает полезный объём и в итоге требует дорогостоящей механической чистки. Из типичных ошибок заказчика повторяются три: не проверяют заранее, пройдёт ли гружёная машина по факту — ширину проезда, высоту арки, место для разворота; заказывают объём впритык, без запаса на неровности заливки; и не берут отдельно бетононасос, когда прямая подача из лотка физически невозможна — заливка выше уровня земли, через забор, в стеснённый котлован. Цена рейса в итоге складывается не из единого «тарифа за куб», а из связки факторов: расстояние именно от того завода, который отгружает нужную марку бетона, заказанный объём, время простоя под разгрузкой сверх заложенного норматива — за превышение начисляется отдельная плата, и отдельная позиция за бетононасос, если подачи из миксера недостаточно.'),
    ],
    'yamobury': [
        ('Как выбрать диаметр и глубину под задачу', 'Диаметр и глубину бурения задаёт не техника, а сама свая или опора. Для временных конструкций — заборов на винтовых сваях, теплиц, времянок — обычно хватает шнека меньшего диаметра из стандартного ряда (150–250 мм) на глубину до двух-трёх метров. Под капитальные фундаменты и опоры ЛЭП диаметр растёт до 350–450 мм, а глубина — до 4–4,5 м на стандартной установке; серийные буровые машины на автошасси (например, БКМ на базе КАМАЗ) комплектуются базовым шнеком около 3,1 м и удлинителями по 1, 1,5 и 2 м для более глубоких скважин. Если проект уже определил диаметр сваи — обычно с шагом 150/200/250/300/350/400 мм под стандартный ряд буровых головок, — эту цифру стоит назвать при заказе: смена головки на объекте не всегда быстрая операция, особенно если под рукой нет нужного типоразмера.\n\nВторой параметр, который часто упускают из виду, — рабочий радиус штанги от места стоянки машины: у установок на автошасси это порядка 7–8 м. Технике не обязательно подъезжать вплотную к каждой точке — важно, чтобы подъезд был в пределах этого радиуса, что особенно критично на стеснённых площадках или там, где уже стоят конструкции.'),
        ('Грунт и сезон: что меняет план работ', 'Скорость и качество бурения определяет прежде всего грунт, а не марка установки. Плотная глина и суглинок с включениями щебня бурятся медленно и создают повышенную нагрузку на редуктор и режущие кромки шнека; сыпучие пески и водонасыщенные грунты, наоборот, осыпаются в скважину сразу после прохода бура — без обсадной трубы яма «гуляет», и свая встаёт с перекосом. Если заказчик заранее не сообщил тип грунта на площадке, бригада рискует приехать не с той комплектацией — это прямой простой на объекте.\n\nВторой фактор — глубина промерзания грунта: опора должна упираться ниже этой отметки, иначе морозное пучение за одну-две зимы вытолкнет её вверх и потянет за собой конструкцию. Нормативная глубина промерзания разная по регионам и типу грунта — в Москве и области, по СП 131.13330.2020, она обычно укладывается в диапазон около 1-1,5 м в зависимости от состава грунта, но точную цифру для конкретного участка и типа грунта нужно смотреть в актуальной редакции норматива под проект, а не брать усреднённый ориентир «полтора метра» на глаз. Зимой верхняя мёрзлая корка грунта дополнительно замедляет проходку и ускоряет износ шнека.'),
        ('Из чего складывается цена и срок', 'Стоимость бурения одной точки — это сумма нескольких переменных, а не фиксированная ставка «за яму»: диаметр и глубина (больше диаметр — дольше проходка и выше износ шнека), тип грунта (глина и щебень бурятся в разы дольше песка), число точек на объекте (мобилизация техники и бригады окупается на серии свай, а не на одной скважине), доступность площадки для разворота машины и расстояние подачи техники до объекта — доля транспортных часов в смете растёт вместе с этим расстоянием. Отдельно на срок влияет необходимость обсадки трубой при нестабильном грунте.\n\nЧастая ошибка заказчика — заказывать бурение без предварительной проверки подземных коммуникаций в зоне работ: за разведку сетей отвечает заказчик, а авария на чужом кабеле или трубе обходится дороже, чем время на согласование. Вторая типичная ошибка — занижать глубину бурения «на глаз», без учёта нормативной глубины промерзания для региона: итог — деформация опоры уже в первую зиму и повторный выезд техники на объект.'),
    ],
    'vilochnye-pogruzchiki': [
        ('Как выбрать грузоподъёмность и тип шасси под задачу', 'Первый критерий выбора — не сама масса груза, а грузоподъёмность на нужной высоте подъёма. У любого вилочного погрузчика фактическая грузоподъёмность снижается по мере подъёма вил и смещения центра тяжести груза от спинки вил: паспортная цифра указана для стандартного расстояния от спинки (обычно около 500 мм) и определённой высоты подъёма, а не как абсолютный максимум на любом вылете и любом ярусе. Поэтому для стеллажного хранения важно сообщать не только вес паллеты, но и высоту, на которую её нужно поднимать, — иначе на объект может приехать модель, которая формально «тянет» нужный вес, но не на нужном ярусе стеллажа. Стандартные погрузчики закрывают диапазон высоты подъёма примерно от 1,5 до 5,5 м; для более высоких стеллажей нужна отдельная, более узкая линейка техники.\n\nПо грузоподъёмности технику условно делят на лёгкую (примерно до 2 т), среднюю (2–4 т), тяжёлую (4–10 т) и большегрузную (свыше 10 т) — большинство складских и монтажных задач закрывают лёгкий и средний классы, тяжёлые и большегрузные нужны для контейнеров, трансформаторов и крупных металлоконструкций. Отдельный вопрос — ходовая часть: трёхопорные (трёхколёсные) погрузчики манёвреннее и разворачиваются в более узком проходе за счёт меньшего радиуса разворота, но при этом их грузоподъёмность обычно ограничена — меньшая опорная база не рассчитана на такие же нагрузки, как у четырёхопорных моделей. Если склад узкий, а грузы тяжёлые, приходится выбирать между шириной прохода и грузоподъёмностью либо брать узкопроходную технику отдельного класса.'),
        ('Дизель, газ или электро — выбор диктует площадка, не бюджет', 'Тип силовой установки определяется условиями работы, а не ценой аренды. Дизельные погрузчики работают практически без ограничений по времени и на любом покрытии, включая грунт и щебень, поэтому это стандартный выбор для открытых площадок, стройплощадок и логистических дворов — но выхлоп делает их непригодными для закрытых непроветриваемых помещений. Погрузчики на газе (пропан-бутан) — компромиссный вариант: ими можно пользоваться в помещении при наличии вентиляции, а смена баллона занимает минуты, в отличие от подзарядки аккумулятора, что удобно при многосменной работе. Электропогрузчики бесшумны и не дают выхлопа, поэтому это обязательный выбор для закрытых складов без вентиляции, пищевых и фармацевтических производств — но за это платят временем: полный цикл зарядки занимает часы, и для круглосуточной работы нужен либо запасной комплект батарей, либо перерыв на подзарядку, который нужно закладывать в график заранее.'),
        ('Типичные ошибки заказчиков и из чего складывается срок и цена', 'Заказчики чаще всего теряют время на две вещи, которые проще уточнить сразу при заявке. Первое — тип покрытия и уклоны площадки: для грунта, щебня или неровного асфальта нужны пневматические шины, для ровного цеха или склада — литые шины (суперэластик), и это разные модели, не взаимозаменяемые «по факту» на объекте. Второе — реальная ширина проездов между стеллажами или техникой: заявленный радиус разворота у стандартного четырёхопорного погрузчика может не вписаться в узкий проход, и это выясняется уже на месте, а не на этапе заявки. Отдельно стоит учитывать допуск оператора — для работы на грузоподъёмной технике нужно действующее удостоверение на данный класс, а при смещённом или подвешенном грузе — дополнительный инструктаж. Срок подачи и цена складываются из доступности нужного класса и высоты подъёма в сети партнёров на конкретную дату, расстояния от точки базирования техники до объекта, длительности работы (почасовая ставка и суточная аренда считаются по-разному) и необходимости нестандартного навесного оборудования — например, зажима для рулонов или удлинённых вил, если груз не типовая паллета.'),
    ],
    'gusenichnye-ekskavatory': [
        ('Как выбрать класс экскаватора под задачу', 'Гусеничные экскаваторы условно делят по эксплуатационной массе на лёгкие (примерно до 10 т), средние (10–30 т) и тяжёлые (свыше 30 т) — эта градация задаёт не только цену подачи, но и то, какие работы машина физически способна выполнить. Лёгкие модели годятся для узких траншей под коммуникации и работы в стеснённых дворах или на уже освоенных площадках, где важна манёвренность, а не глубина копания. Средний класс — рабочая лошадка большинства строительных объектов: у машин массой 10–30 т обычно достаточный вылет стрелы и глубина копания, чтобы отрывать котлован под фундамент малоэтажного здания или прокладывать траншею под магистральный трубопровод за один проход, без докапывания вручную. Тяжёлые экскаваторы применяют там, где важен не столько глубина копания, сколько объём ковша за цикл — карьерная разработка, масштабная вертикальная планировка, снятие большого объёма грунта в сжатые сроки. Типичная ошибка заказчиков: заказывают технику «с запасом», ориентируясь только на массу, а не на реальные параметры вылета стрелы и глубины копания под конкретный объект — в результате либо переплачивают за простаивающий тяжёлый класс, либо берут лёгкую машину, которая не докапывает до проектной отметки и требует повторного захода.'),
        ('Логистика подачи: трал, площадка, сезон', 'Доставка гусеничного экскаватора на объект — отдельная задача, которая часто занимает больше времени, чем подготовка самой техники. Машины среднего и тяжёлого класса не передвигаются своим ходом по дорогам общего пользования и перевозятся низкорамным тралом; в зависимости от массы и габаритов может потребоваться оформление разрешения на перевозку крупногабаритного или тяжеловесного груза и, при превышении определённых порогов, машина сопровождения — это нужно закладывать в срок подачи заранее, а не решать в день выезда. Второй момент, который часто упускают заказчики, — состояние самой площадки: гусеничный ход снижает удельное давление на грунт по сравнению с колёсной техникой, но не отменяет требований к несущей способности основания — на слабых, переувлажнённых или недавно отсыпанных грунтах экскаватор может увязнуть или потерять устойчивость при работе с вылетом стрелы. В межсезонье (распутица, оттепель) это особенно актуально: подъездные пути и саму площадку нужно подготовить — отсыпать, уплотнить — до прибытия техники, иначе подачу приходится переносить или привлекать дополнительную технику для подготовки проезда.'),
        ('Из чего складывается цена и срок подачи', 'Стоимость работы гусеничного экскаватора складывается не из одной ставки за час, а из нескольких статей: сама аренда техники нужного класса, доставка тралом (зависит от расстояния, массы машины и необходимости разрешений на негабарит), длительность работ на объекте и часто отдельная оплата подачи и снятия с трала на площадке. На срок подачи влияет доступность нужного класса техники в конкретном регионе на дату работ, расстояние до ближайшей подходящей машины и сезонный спрос — в разгар строительного сезона технику стоит резервировать заранее, а не в день, когда она нужна на объекте. Понимание этой структуры позволяет сравнивать предложения корректно: цена «за час работы» без учёта доставки и класса техники часто даёт неполную картину.'),
    ],
    'bortovye-dlinnomery': [
        ('Как выбрать длину платформы и грузоподъёмность', 'Отправная точка — не грузоподъёмность сама по себе, а совпадение трёх параметров: длина груза, его развесовка по платформе и способ погрузки. Стандартная длина борта-длинномера — 13,6 м: тот же размер, что и у полуприцепов еврофур, рассчитанный под сетку из 33 европаллет, и под него проще всего подобрать машину без лишних формальностей. Если груз (труба, балка, свая) длиннее платформы и выступает за неё, важно свериться с общими нормами перевозки: без специального разрешения свес груза за габариты кузова не должен превышать 2 м, а полная длина автопоезда — 20 м (для одиночного транспортного средства — 12 м). Груз в 14–15 м на платформе 13,6 м — уже пограничный случай, где стоит заранее точно измерить длину и развесовку, а не полагаться на глазомер, иначе машину придётся подавать уже как везущую негабарит. С марта 2024 действует и единый норматив по ширине — 2,6 м для любого типа кузова, раньше для открытых платформ и тентованных значения различались. Второй критерий — характер нагрузки: трубы и балки лежат на кониках точечно, и здесь важнее не паспортная грузоподъёмность борта в целом, а то, как груз ляжет на конкретные точки рамы, тогда как плиты и ЖБИ дают более равномерную нагрузку, и для них важнее ровный пол платформы, а не расстановка стоек.'),
        ('Крепление груза и когда это уже негабарит', 'Груз на открытой платформе держится на кониках, стяжных ремнях, цепях и упорных стойках — здесь нет права закрепить «на глаз»: важно, чтобы груз не сдвинулся ни вбок, ни назад при торможении, а стойки выдержали боковую нагрузку длинного профиля, а не только его вес сверху вниз. Дальше начинается организационная, а не техническая часть. Если длина автопоезда превышает 25 м или ширина — 3,5 м, по правилам перевозки уже нужны машины сопровождения (минимум одна спереди и одна сзади). При ширине свыше 5 м или длине свыше 35 м требуется отдельно согласовывать маршрут — то есть готовить и утверждать проект мер по безопасности движения на весь путь следования. Это не абстрактные цифры «для больших грузов»: длинномерная балка или ферма нестандартной длины довольно быстро подводит машину к этим порогам, особенно если платформу приходится удлинять сверх стандартных 13,6 м. Отсюда прямое следствие для сроков: обычный борт можно подать в день заявки, а под груз с пропусками и сопровождением закладывайте несколько дней на согласование маршрута — это не тянется дольше по вине перевозчика, а требует времени по регламенту.'),
        ('Из чего складывается цена и сроки подачи', 'Смена борта с обычным грузом стоит дешевле в первую очередь потому, что не требует ни манипулятора, ни сопровождения, ни согласований — цена растёт с каждым добавленным фактором: расстояние и время в пути до объекта, способ погрузки (самостоятельная погрузка бортом с КМУ обходится дороже стороннего крана, но экономит время и отдельный заказ грузоподъёмной техники), и переработка сверх стандартной смены при задержках на погрузке-разгрузке. Отдельно стоит учитывать сезонность на межгородних маршрутах: в марте-апреле на региональных и местных дорогах (федеральные трассы это не затрагивает) вводят временные ограничения по нагрузке на ось на 30–60 дней, сроки и предельные значения каждый регион устанавливает самостоятельно. Если маршрут длинномера с гружёной платформой идёт не по федеральной трассе, а пересекает региональную сеть, в этот период груз может либо не пройти по факту, либо потребовать объезд — это стоит закладывать в сроки на этапе планирования, а не выяснять по факту в дороге.'),
    ],
    'pnevmokolesnye-krany': [
        ('Как выбрать класс крана под задачу', 'Не стоит формулировать заявку как «нужен кран на 25 тонн» — паспортная грузоподъёмность достигается только на минимальном вылете стрелы, а на объекте груз обычно нужно поднять и пронести в сторону, за пределы опорного контура. Подбор модели идёт от двух реальных цифр: вылета (расстояние от оси крана до точки монтажа) и высоты подъёма груза с этого вылета — именно эта пара, а не максимальная паспортная тонна, определяет, какая машина нужна. Второй параметр — площадка. Пневмоколёсный кран работает на выносных опорах (аутригерах), и полная грузоподъёмность по грузовысотной характеристике доступна только при их полном разворачивании на подготовленном, выровненном основании. Если площадка стеснена и опоры разворачиваются не на полную длину, кран переходит на уменьшенную грузовую таблицу — это нужно закладывать в заявку заранее, а не выяснять на объекте в день монтажа.'),
        ('Чем пневмоколёсный кран отличается от автокрана на практике', 'У пневмоколёсного крана собственное шасси — не грузовой автомобиль, а колёсная база с более широко расставленными парами колёс, чем у автокрана на шасси КамАЗ или МАЗ. За счёт этого часть операций можно вести с ограниченной нагрузкой прямо на ходу, без полного разворачивания опор — но это ограниченный режим по сокращённой грузовой таблице, а не замена штатной работе на аутригерах. Обратная сторона широкой базы и жёсткой подвески ходовой части — скорость: по паспорту такие краны передвигаются медленнее автокрана, как правило не быстрее 20 км/ч. Поэтому на дальние расстояния между объектами их не гоняют своим ходом, а перевозят на трале — и это отдельная строка в логистике и в сроке подачи, которую нужно закладывать заранее, а не в день монтажа.'),
        ('Из чего складывается цена и срок подачи', 'Стоимость подачи пневмоколёсного крана — это не только ставка за смену или час работы стрелой. В неё входит доставка до объекта (трал, если кран едет издалека, — с учётом габарита машины и возможных разрешений при негабаритной перевозке), время на разворачивание и уборку опор и стрелы непосредственно на площадке, и погодное окно: работа на большом вылете ограничивается по силе ветра, и это может сдвинуть монтаж на другой день независимо от готовности техники и бригады. Поэтому вылет, высоту подъёма, тип основания площадки и подъезд к ней мы уточняем у заказчика ещё на этапе заявки — это даёт возможность подобрать подходящую модель из проверенной партнёрской сети и назвать реалистичный срок подачи, а не примерную вилку по телефону.'),
    ],
    'vezdehodnye-krany': [
        ('Когда без вездеходного шасси не обойтись', 'Вездеходный кран нужен не потому что стройка «сложная», а потому что к объекту физически нет дороги с твёрдым покрытием — карьер, трасса ЛЭП, поле под фундамент, площадка на месторождении, зона паводка. Ключевой критерий выбора — не грузоподъёмность сама по себе, а несущая способность грунта на подъездных путях и под опорами: автокран на шоссейном шасси с колёсной формулой 6х4 с высокой вероятностью застрянет там, где полноприводная машина 6х6 пройдёт. Второй критерий — сезон: весенняя и осенняя распутица резко сужают круг техники, которая вообще способна доехать, и это нужно закладывать в заявку заранее, а не решать в день подачи. Третий — реальное состояние площадки под опоры: на слабом или переувлажнённом грунте крану нужна увеличенная площадь опирания или подкладки под опорные лапы (грунтовые плиты, маты), и это стоит проговорить с диспетчером на этапе заказа, а не по факту приезда техники на объект.'),
        ('Проходимость шасси: что реально важно', 'Главное конструктивное отличие вездеходного крана от дорожного — не стрела и не грузоподъёмность, а шасси: колёсная формула 6х6, где ведущие все оси, вместо привычной для магистральных кранов 6х4, и у части машин — централизованная система регулирования давления воздуха в шинах. Она позволяет водителю менять давление прямо из кабины, не останавливаясь и не выходя: снижать его при переходе с асфальта на рыхлый песок, заболоченный участок или целинный снег, чтобы увеличить площадь пятна контакта и проходимость, а на обратном пути к трассе — поднимать давление для нормального ресурса резины. При проколе или повреждении шины система даёт возможность доехать на постоянной подкачке до места ремонта, не меняя колесо прямо в поле. Это не опция для галочки в спецификации, а то, что на практике решает, доедет кран до площадки в распутицу своим ходом или его придётся тащить тягачом.'),
        ('Типичные ошибки заказчиков и из чего складывается цена', 'Частая ошибка заказчика — брать вездеходный кран «на всякий случай», хотя объект вполне доступен для обычного шоссейного крана: это не вопрос безопасности, а переплата, потому что таких машин в парках партнёров меньше и логистика их подачи дороже. Обратная и более критичная ошибка — заказать обычный автокран туда, где нет дороги: в лучшем случае это простой в ожидании эвакуации, в худшем — застрявшая техника и сорванный график монтажа. Из чего реально складываются цена и срок подачи: расстояние и состояние подъездных путей от базы ближайшего партнёра, а не от города вообще; необходимость подготовки площадки под опоры на мягком грунте; сезонный фактор — распутица увеличивает время в пути и иногда требует сопровождения; и собственно продолжительность работы на объекте. Тип грунта, доступность подъезда и реальные сроки мы сверяем с диспетчером партнёрской сети до выезда техники — это дешевле, чем разбираться с этим по факту на площадке.'),
    ],
    'korotkobaznye-gorodskie-krany': [
        ('Как выбирать модель под конкретную площадку', 'Для этого класса техники ключевой параметр — не грузоподъёмность сама по себе, а соотношение колёсной базы и требуемого вылета опор к реальным габаритам подъезда. У короткобазных автокранов база шасси укорочена примерно до 3,2–3,8 м, за счёт чего минимальный радиус разворота сокращается до 7–9 метров — машина проходит там, где кран на обычной базе вынужден сдавать назад несколько раз или вообще не заезжает во двор. Но короткая база не отменяет требований к пятну установки: телескопическая стрела у таких машин обычно 20–30 м, а с дополнительной секцией (гуськом) общая высота подъёма увеличивается до 35 м, и опоры при работе на таком вылете раскладываются практически так же широко, как у полноразмерного крана. Поэтому перед подбором модели диспетчеру нужны не паспортные максимумы, а три конкретные цифры с объекта: фактическая ширина проезда и арок, расстояние от возможной точки стоянки крана до точки подъёма груза, и вес груза на этом вылете — потому что грузоподъёмность на большом вылете у короткобазных машин часто снижается заметнее, чем у крана с той же базовой грузоподъёмностью, но обычной базой. Модель, подобранная только по цифре на table «до N тонн» без грузовой характеристики на нужном вылете, — частая причина того, что кран приезжает и не может взять груз.'),
        ('Где короткая база уже не решает', 'Короткобазный кран остаётся полноразмерной колёсной машиной, и есть сценарии, где даже 7–9-метровый радиус разворота не помогает: заезд через арку у́же кранового шасси, работа в закрытом дворе-колодце или на площадке, где физически негде разложить классические выносные опоры. Для таких случаев в проверенной сети есть более компактная альтернатива — гусеничные или колёсные мини-краны с раскладными опорами («краны-пауки»): опоры у них расходятся в стороны шире, чем корпус машины, обеспечивая устойчивость на неровном или слабом основании при заметно меньшем пятне установки, чем у автокрана любой базы. Выбор между короткобазным автокраном и краном-пауком — вопрос не цены, а буквально диаметра площадки: если места хватает только на саму машину без раскладки штатных опор, короткая база проблему не решает независимо от заявленной грузоподъёмности, и здесь нужно сразу переходить к другому классу техники.'),
        ('Из чего на самом деле складываются цена и срок', 'Итоговая стоимость и сроки подачи короткобазной техники редко определяются одной ставкой за смену. На них влияют: расстояние подачи техники до объекта — это не самый массовый класс кранов, и ближайшая свободная машина может стоять дальше, чем ближайший стандартный автокран; минимальное время заказа, которое диспетчер обычно оговаривает отдельно для разовых коротких работ; необходимость частичного демонтажа стрелы или гуська, если кран не проходит по маршруту в собранном виде; и простой, если площадка не готова к моменту подачи — не расчищен подъезд или не согласовано место установки опор. Типичная ошибка заказчика — согласовывать вызов техники по одной цифре «грузоподъёмность крана», не уточнив у диспетчера фактический вылет до точки подъёма и вес груза вместе с такелажем и стропами: это меняет класс нужной модели и, соответственно, цену уже на месте. Второй частый промах — не проверить заранее, что находится под предполагаемой точкой установки опор: подземные коммуникации, теплотрассы, кабельные линии. Под нагрузкой это риск не только простоя, а повреждения сетей, поэтому правильная практика — согласовывать точку установки опор до подачи техники, а не по факту приезда крана на объект.'),
    ],
    'krany-na-spetsshassi-all-terrain': [
        ('Как выбрать класс крана под конкретную задачу', 'Грузоподъёмность в характеристиках модели — это цифра на минимальном вылете у опоры, а не универсальный показатель: с каждым метром вылета максимальный груз падает по грузовысотной характеристике конкретной модели. Поэтому для подбора крана недостаточно назвать вес груза — нужны фактический вылет от оси крана до точки установки и требуемая высота подъёма на этом вылете. Без этих двух цифр формулировка «нужен кран на 25 тонн» ничего не говорит о том, поднимет ли он груз именно на вашем объекте.\n\nВторой критерий — число осей шасси. У кранов на спецшасси All Terrain оно варьируется примерно от трёх до девяти в зависимости от класса грузоподъёмности, и от числа осей напрямую зависит распределённая нагрузка на ось при движении по дорогам общего пользования — а значит, потребуется ли спецразрешение на проезд (см. следующий раздел). Третий критерий — реальная площадка под выносные опоры: ширину их выдвижения и допустимое давление на грунт нужно сверять с фактическим пятном застройки на объекте, особенно во дворах и на стеснённых городских площадках, а не с паспортными данными «в идеальных условиях».'),
        ('Проезд по дорогам: разрешения и сезонные ограничения', 'Допустимая нагрузка на ось на дорогах общего пользования в России обычно ограничена диапазоном порядка 5–11 тонн в зависимости от типа дорожного покрытия и конкретного участка. Тяжёлый кран на спецшасси с фактической осевой нагрузкой выше этого порога не может выехать на трассу «просто своим ходом» — на такую технику оформляется специальное разрешение, а в ряде случаев требуется сопровождение. Оформление занимает время, и его нужно закладывать в срок подачи заранее, а не в день заявки.\n\nДополнительный сезонный фактор — весенние ограничения движения большегрузов («просушка»), которые регионы вводят на региональных и межмуниципальных дорогах после схода снега, когда несущая способность полотна временно снижается. Сроки и жёсткость ограничений отличаются по регионам: где-то это несколько недель, в северных регионах со слабыми грунтовыми дорогами — дольше. В этот период маршрут, обычно доступный без разрешения, может потребовать отдельного пропуска или объезда — это стоит учитывать при планировании подачи техники в период с марта по май.'),
        ('Из чего складывается цена и срок подачи', 'Стоимость подачи крана на спецшасси — это не только почасовая ставка работы на объекте. В неё входит перегон техники (расстояние, состояние дороги и необходимость спецразрешения — см. выше), время на монтаж и демонтаж стрелы и противовеса под требуемую грузовысотную характеристику — у моделей крупного класса это может занимать не один час, — сама продолжительность подъёмных работ и класс/грузоподъёмность крана: чем выше тоннаж, тем дороже и техника, и её эксплуатация.\n\nТипичная ошибка заказчика — заказывать кран «с запасом» по паспортной грузоподъёмности, не сверяя её с фактическим вылетом на объекте. На месте нередко выясняется, что заявленная модель не берёт груз на нужном плече, и подачу приходится переоформлять на более тяжёлый класс — с потерей времени на объекте и пересчётом стоимости. Чтобы этого избежать, вылет и высоту подъёма стоит фиксировать в заявке до подбора модели, а не после.'),
    ],
    'mini-krany-paukoobraznye': [
        ('Как выбрать грузоподъёмность и модель под задачу', 'Паспортная максимальная грузоподъёмность мини-крана почти всегда указана для минимального вылета стрелы — обычно это 1,5–3 м от оси машины. При увеличении вылета грузоподъёмность падает по грузовой характеристике (load chart) в разы, и на реальной дистанции до точки монтажа кран может поднять заметно меньше, чем заявлено в характеристиках модели. Поэтому диспетчеру нужно называть не просто вес груза, а фактический вылет (расстояние от точки, где кран физически может встать, до точки подъёма) и высоту подъёма — только так можно подобрать модель, а не типоразмер «на глаз».\n\nВторой параметр — габариты проезда. У части моделей этого класса корпус в транспортном/сложенном положении сужается до 700–800 мм, что позволяет завести технику через стандартный дверной или воротный проём, лестничный марш, в лифтовой холл. Но это касается не всех моделей — узкий корпус нужно уточнять отдельно под конкретный проём.\n\nТретий параметр — тип привода. Дизельные и бензиновые версии дают эксплуатационные выхлопные газы, поэтому для работы внутри непроветриваемых помещений (склад, цех, атриум, подвал) нужна модель с электрическим или аккумуляторным приводом — эта опция есть не на всех модификациях.'),
        ('Опоры, ход и управление: на что смотреть в эксплуатации', 'Гусеничный ход даёт мини-крану проходимость по мокрому грунту, наледи, снегу и грязи — там, где колёсная техника буксует. В сочетании с независимо регулируемыми опорами (каждая нога выставляется на свою высоту) это позволяет работать на лестницах, уклонах и неровных площадках, недоступных для автокрана. Обратная сторона: перед выездом на чистовые покрытия — плитку, ламинат, наливной пол, кровельный настил — нужны опорные маты под каждую опору, потому что вся масса крана и груза распределяется всего на 3–4 точки, и точечная нагрузка на палец опоры способна продавить или расколоть покрытие.\n\nРадиоуправление позволяет оператору находиться непосредственно рядом с грузом и визуально контролировать монтаж — это особенно важно при установке остекления, инженерного оборудования, конструкций в стеснённых внутренних пространствах, где стрелу нужно провести между уже смонтированными элементами.'),
        ('Типичные ошибки заказчиков и из чего складывается цена', 'Самая частая ошибка — заявка по одному весу груза без вылета и высоты. На объекте выясняется, что на нужном расстоянии до точки монтажа кран не вытягивает заявленный груз, и модель приходится менять уже после подачи техники, что срывает график. Вторая ошибка — не продуман подъезд: паук доставляется на прицепе или манипуляторе и дальше заезжает на площадку своим ходом, но для этого нужен свободный проезд для доставляющего транспорта и место для разгрузки — в плотной дворовой застройке это стоит уточнять заранее, а не в день подачи.\n\nЗимой гусеничный ход работает надёжнее колёсного, но площадку под опоры всё равно нужно очищать от наста и льда — под нагрузкой он проседает неравномерно, и кран может потерять горизонт уже после выставления опор.\n\nИтоговая цена и срок складываются из класса и грузоподъёмности модели под конкретный вылет, продолжительности работ и минимального заказа по времени, сложности подачи техники на объект (доступность подъезда, этаж, наличие лифта или необходимость заводить кран по частям) и часто — включённого оператора, поскольку мини-краны такого класса сдаются в аренду вместе с экипажем, а не как самостоятельная техника.'),
    ],
    'samomontiruyushchiesya-bashennye-krany': [
        ('Когда нужен именно самомонтирующийся кран, а не обычный башенный', 'Самомонтирующиеся башенные краны — отдельный класс техники, который решает конкретную задачу: поднять груз на площадке, где нет места и времени разворачивать классический башенный кран с помощью отдельного гусеничного или автомобильного крана для монтажа. Их имеет смысл заказывать для малоэтажного строительства — коттеджей, таунхаусов, объектов в 2–5 этажей, — для реконструкции в стеснённой городской застройке и для проектов, где кран приходится несколько раз переставлять с площадки на площадку. Ключевое отличие от классических башенных кранов — грузоподъёмность: у самомонтирующихся моделей она обычно измеряется единицами тонн (например, у Potain IGO36 паспортная грузоподъёмность около 4 т), тогда как у крупных башенных кранов — десятками тонн. Поэтому при подборе смотрят не на паспортный максимум, а на грузоподъёмность на конкретном рабочем вылете стрелы: именно она определяет, потянет ли кран монтаж плит перекрытия или блоков на нужном расстоянии от оси. Есть и обратная сторона компактности: самомонтирующиеся краны легче классических башенных, поэтому для открытых, продуваемых площадок отдельно уточняют ограничения по ветровой нагрузке и по высоте свободностоящей работы — это влияет на выбор модели не меньше, чем этажность объекта.'),
        ('Как устроен самомонтаж и что это меняет для площадки', 'Главное конструктивное отличие этого класса — кран монтируется сам, за счёт собственных гидравлических и электрических систем, без вызова отдельной техники и без верхолазных работ. Это меняет логистику: не нужно отдельно заказывать и оплачивать автокран или гусеничный кран под монтаж и демонтаж, монтажная бригада обычно меньше, чем у классического башенного крана, а сама раскладка занимает часы, а не дни. Требования к площадке под сам кран при этом никуда не деваются: нужна подготовленная ровная площадка под опоры на весь период работы — с учётом веса крана в рабочем положении и вылета противовеса. Ещё один нюанс — время года: подготовка твёрдого основания под опоры на мёрзлом или переувлажнённом грунте занимает заметно больше времени, чем летом, и это стоит закладывать в график, если монтаж планируется на зиму или в распутицу. Перед подбором стоит уточнить у заказчика фактические размеры площадки, тип покрытия и подъезд для доставки — кран всё равно приезжает на трале, и его нужно куда поставить.'),
        ('Из чего складывается цена и в чём чаще всего ошибаются заказчики', 'В стоимость входят доставка крана на объект и обратно, аренда за период — посуточно или помесячно, в зависимости от срока проекта, — сама операция монтажа/демонтажа (у самомонтирующихся моделей она быстрее и дешевле, чем демонтаж классического башенного крана силами стороннего мобильного крана) и работа крановщика на весь срок аренды. Сильнее всего на итоговую цену влияют срок аренды и число перестановок крана на площадке — если объект растянут во времени или кран нужно переносить между корпусами, это стоит уточнять на этапе заявки, а не после подачи техники. Частая ошибка заказчиков — подбирать самомонтирующийся кран по принципу «лишь бы был башенный», не сверив грузоподъёмность на рабочем вылете с реальным весом поднимаемых элементов — плит перекрытия, блоков, поддонов с кирпичом — и высотой объекта. У этого класса кранов высота подъёма и вылет стрелы ограничены заметно сильнее, чем у крупных башенных кранов, поэтому под многоэтажный монолит или объект с большим пятном застройки его закладывать не стоит — там нужен уже обычный башенный кран с монтажом отдельной техникой.'),
    ],
    'bystromontiruemye-bashennye-krany': [
        ('Найденные факты (WebSearch)', '1) Быстромонтируемый (самомонтируемый) башенный кран собирается на объекте собственными гидравлическими механизмами, без верхолазных работ и без отдельного крана-монтажника; в зависимости от модели раскладка занимает от нескольких десятков минут до нескольких часов, бригадой обычно из 2-3 человек (источники: ru.wikipedia.org/wiki/Быстромонтируемый_кран, cnxjcm.com/ru/fast-erecting-vs-self-erecting-cranes-which-saves-more-time). 2) Такие краны часто работают на выдвижных опорах с балластом, поэтому капитальный фундамент в классическом виде не обязателен — но опорная база под опоры всё равно рассчитывается индивидуально: производитель даёт значения реакций (нагрузку на опору) для конкретной высоты, вылета и конфигурации противовеса, и эти значения нельзя перенести с другого объекта или модели; при подготовке площадки проверяют грунт, укладывают подкладки, закладывают уклон под отвод воды (источник: glavarendakran.com — статьи про фундамент башенного крана). Общеинженерный факт (не требует отдельной проверки, это базовый принцип грузовой характеристики любого стрелового/башенного крана): паспортная максимальная грузоподъемность указывается для минимального вылета стрелы и падает с ростом вылета — важно для подбора модели под конкретную точку подъема. Номера ГОСТ/СНиП/статей закона нигде не упоминались и в текст НЕ включены (не найдено точного подтверждения конкретного нормативного документа под эту тему).'),
        ('Готовый текст для страницы (3 подраздела, ~410 слов)', '## Как выбрать модель под конкретный объект\n\nКлючевая ошибка при подборе быстромонтируемого башенного крана — ориентироваться на паспортную максимальную грузоподъемность. Она указывается для минимального вылета стрелы, у самого ствола, а по мере увеличения вылета грузоподъемность падает — это стандартная грузовая характеристика любого стрелового или башенного крана. Для конкретной точки подъема, например монтажа плиты перекрытия на дальнем углу здания, нужно смотреть значение именно на нужном вылете, а не верхнюю цифру из характеристик модели. Второй параметр — высота подъема крюка: если кран ставится на весь цикл монолитных или каркасных работ, запас по высоте закладывают не под текущую этажность, а под финальную отметку здания. Третий — тип опорной базы. Часть моделей работает на выдвижных опорах с балластом, что даёт компактный след и подходит для стесненной городской площадки, часть — на рельсовом ходу или портале с возможностью перемещения вдоль здания, что удобнее на протяженных объектах с несколькими зонами подъема.\n\n## Монтаж и требования к площадке\n\nОтличие быстромонтируемого крана от классического приставного или самоподъёмного — он собирается собственными гидравлическими механизмами, без верхолазных работ и без отдельного крана-монтажника. В зависимости от модели раскладка занимает от нескольких десятков минут до нескольких часов, бригадой обычно из двух-трёх человек. Но это не отменяет подготовку площадки: под выдвижные опоры всё равно нужна расчётная опорная база. Производитель даёт значения реакций — нагрузку на каждую опору — для конкретной высоты подъема, вылета стрелы и конфигурации противовеса, и эти цифры нельзя перенести «по аналогии» с соседнего объекта или с другой модели крана. На практике перед установкой проверяют несущую способность грунта под опорами, укладывают инвентарные плиты или подкладки, закладывают уклон для отвода воды — и учитывают, что после сильного дождя или в период оттепели площадку часто приходится готовить заново непосредственно перед монтажом.\n\n## Из чего складывается срок и стоимость\n\nСрок и стоимость подачи крана редко сводятся к одной цифре аренды за сутки или месяц. В расчёт входит доставка — кран и его секции с противовесами едут как крупногабаритный груз, и число рейсов зависит от модели и высоты подъема; монтаж и демонтаж как отдельный этап работ, отдельный от почасовой или посуточной ставки самого крана; при необходимости — расчёт и подготовка опорной базы под конкретный грунт, если типовое решение не подходит; и собственно период работы крана на объекте. Для коротких по времени задач — день-два, например монтаж одной конструкции — экономически чаще выгоднее автокран или гусеничный кран сопоставимой грузоподъемности: у них нет отдельного этапа монтажа/демонтажа опорной базы. Быстромонтируемый башенный кран оправдан там, где он нужен на площадке несколько недель или месяцев подряд — тогда стоимость монтажа и демонтажа распределяется на весь срок работы и перестаёт быть заметной статьёй расхода.\n\nПроверено: текст не содержит вымышленных цифр, номеров ГОСТ/СНиП или упоминаний «наш парк» / «собственная техника» во множественном числе — только проверяемые через WebSearch факты и общеинженерные принципы.'),
    ],
    'kozlovye-krany': [
        ('Как выбрать пролёт, грузоподъёмность и схему опор', 'Ошибка №1 при подборе козлового крана — смотреть только на паспортную грузоподъёмность модели. Важны три параметра вместе: пролёт, грузоподъёмность на консоли (если она нужна) и высота подъёма с учётом грузозахватного приспособления. Пролёт — это расстояние между рельсами, его считают не по ширине штабеля «на глаз», а с запасом под подкрановые балки и проезд транспорта под краном. Если груз грузится или снимается за пределами рельсового пути — сбоку от фуры, за линией штабеля, — нужна модель с консолями, и на консоли допустимая нагрузка у большинства кранов ниже, чем в середине пролёта: это уточняют по паспорту конкретной машины, а не берут максимальное число из таблицы. Высоту подъёма считают не по высоте штабеля, а с запасом на высоту траверсы, спредера или стропов — они «съедают» часть хода крюка сверху. Отдельный момент — конструкция опор: у кранов с небольшим пролётом обе опоры обычно жёсткие, у кранов с большим пролётом одну чаще делают шарнирной — она компенсирует разницу в осадке пути и температурные деформации моста. Поэтому две модели с одинаковой грузоподъёмностью и похожим пролётом могут заметно отличаться по цене и требованиям к путям. И отдельный вопрос — рельсовый кран или пневмоколёсный (RTG): рельсовый выгоднее там, где кран стоит на одном месте месяцами (терминал, склад, площадка ЖБИ), пневмоколёсный удобнее при разовых задачах и смене площадки, но требует ровного твёрдого покрытия.'),
        ('Подкрановые пути и сезонность: где обычно теряют время', 'Рельсовый козловой кран — это не только металлоконструкция, но и путь под ней, и именно путь чаще всего определяет реальный срок проекта. Перед укладкой рельсов площадку готовят: снимают растительный слой и мусор, отсыпают и уплотняют насыпь, устраивают балластное основание — его толщина и несущая способность зависят от грунта и режима работы крана, поэтому расчёт для одной площадки не подходит другой без проверки. После монтажа путей обязательна обкатка: кран несколько раз прогоняют по всей длине пути без груза, затем с контрольным весом, чтобы выявить слабые участки насыпи до того, как кран встанет под полную нагрузку. Пропускать этот шаг нельзя даже под давлением сроков — просадка пути под нагруженным краном обходится дороже, чем день на обкатку. Сезонность добавляет свои ограничения: зимой основание расчищают от снега и льда до начала земляных работ, а промёрзший или, наоборот, оттаявший по весне грунт меняет несущую способность насыпи. Если монтаж планируется на зиму или раннюю весну, время на подготовку основания закладывают в график отдельно от времени на сборку самого крана.'),
        ('Из чего складывается цена и типичные ошибки в расчёте бюджета', 'Стоимость проекта с козловым краном почти никогда не равна стоимости смены или аренды самой машины. В неё входят доставка — кран обычно разбирается на секции и едет на площадку тралом, — монтаж и пусконаладка, устройство или проверка подкрановых путей, если они ещё не готовы или не рассчитаны под конкретную модель, обкатка после монтажа и, для стационарной установки, постановка крана на учёт и техническое освидетельствование. Самая частая ошибка заказчика — планировать бюджет и срок по цене смены крана, не заложив время и деньги на путь: если рельсы нужно строить с нуля, подготовка основания и обкатка нередко занимают больше времени, чем монтаж самой металлоконструкции. Вторая типичная ошибка — выбирать модель по грузоподъёмности «в центре пролёта», не проверив, сколько кран реально поднимет там, где груз будет сниматься фактически — на консоли или у края пути, где допустимая нагрузка обычно ниже паспортного максимума. Обе ошибки не про деньги на сам кран, а про то, что путь и площадку нужно проектировать вместе с краном, а не после того, как машина уже выбрана.'),
    ],
    'mostovye-krany': [
        ('Как выбрать тип и грузоподъёмность крана', 'Мостовые краны бывают опорные и подвесные, и разница — не в терминологии, а в том, что может выдержать здание. У опорного крана мост опирается сверху на подкрановые рельсы, закреплённые на колоннах цеха или на отдельной эстакаде — такая конструкция берёт на себя более серьёзные нагрузки. Подвесной кран крепится снизу, к поясам перекрытия, и ограничен по пролёту и грузоподъёмности — зато не требует усиления колонн и обходится дешевле там, где грузы небольшие. Выбор типа почти всегда определяется не пожеланиями, а тем, что показывает проект здания или обследование существующих конструкций.\n\nС грузоподъёмностью то же самое: краны условно делятся на три диапазона — до 5 т (обычно однобалочные краны-балки для лёгкого монтажа и мелкосерийного производства), 5–50 т (основной диапазон для большинства цехов, часто с двумя механизмами подъёма — главным и вспомогательным, что удобно при разных по массе грузах) и свыше 50 до 320 т — тяжёлая техника для металлургии и крупного машиностроения. Дополнительно к грузоподъёмности всегда сверяют пролёт и высоту подъёма с реальными размерами помещения — иначе кран физически не пройдёт под перекрытием или не дотянется до нужной точки.'),
        ('Режим работы и эксплуатационные нюансы', 'Помимо грузоподъёмности у крана есть параметр, о котором заказчики часто забывают — группа режима работы по действующему ГОСТ 34017-2016 «Краны грузоподъёмные. Классификация режимов работы» (пришёл на смену старому ГОСТ 25546-82, соответствует международному ISO 4301). Она определяется двумя вещами: классом использования (сколько рабочих циклов кран должен выдержать за срок службы) и классом нагружения (насколько фактические нагрузки близки к номинальным) — от эпизодической лёгкой работы, характерной для ручных кранов-балок, до непрерывной интенсивной работы с нагрузками, близкими к предельным, характерной для металлургических цехов. Если взять кран с заниженной группой режима под интенсивное многосменное производство, механизмы и металлоконструкция вырабатывают ресурс кратно быстрее паспортного срока; если наоборот — переплата за запас, который не понадобится.\n\nОтдельно стоит учитывать состояние и параметры подкранового пути — если кран монтируется в существующем здании, рельсы и их положение нужно сверять с допусками производителя крана, а не рассчитывать, что подойдут «любые старые рельсы»: отклонения ведут к перекосу моста и ускоренному износу ходовых колёс. И ещё один момент, который стоит закладывать в график заранее: мостовой кран как грузоподъёмное сооружение подлежит техническому освидетельствованию и учёту — это отдельная процедура, идущая параллельно с монтажом, а не после него.'),
        ('Типичные ошибки заказчиков и из чего складывается цена', 'Самая частая ошибка — подбирать грузоподъёмность «с запасом», не проверив высоту помещения под фермами и габариты крана в сборе: техника с нужной паспортной грузоподъёмностью просто не проходит по высоте или задевает коммуникации. Вторая по частоте — не учитывать вес крюковой подвески или траверсы в полезной грузоподъёмности, из-за чего фактически поднимаемый груз оказывается меньше расчётного. Третья — заказывать кран без учёта реальной интенсивности работы: лёгкий однобалочный кран для эпизодического использования, поставленный на участок с многосменной загрузкой, требует ремонта в разы раньше, чем рассчитывал заказчик.\n\nЦена и срок подачи мостового крана складываются из нескольких вещей: пролёта и грузоподъёмности (крупные краны часто делаются под заказ, а не берутся со склада), группы режима работы, типа управления (кабина или радиопульт), состояния подкранового пути — нужно ли его монтировать заново или использовать существующий, — и логистики: доставки, монтажа и последующего технического освидетельствования. Мы уточняем эти параметры до подачи заявки поставщику из проверенной партнёрской сети, чтобы не подавать заявку вслепую и не менять кран на площадке уже после монтажа.'),
    ],
    'portalnye-krany': [
        ('Как выбрать портальный кран под конкретную задачу', 'Грузоподъёмность портального крана — это не одно число, а кривая: она снижается по мере увеличения вылета стрелы. У большинства портальных кранов вылет варьируется в диапазоне 15–50 м, но на практике чаще всего работают модели с вылетом около 30 м — этого хватает для обработки судна у причала без лишнего перезаказа техники. При подборе нужно смотреть не на паспортный максимум грузоподъёмности, а на грузовысотную характеристику именно на том вылете, где реально будет вестись работа: груз у борта судна и груз в глубине причального склада требуют разного вылета стрелы, и допустимая масса груза на них отличается в разы.\n\nВторой параметр — высота портала (расстояние от рельсов до поворотной платформы), у типовых кранов 15–30 м. Она задаёт клиренс: под порталом должен свободно проходить железнодорожный состав или колёсная техника, если проезд организован именно там, а не сбоку. Третий параметр — скоростные характеристики цикла: скорость подъёма у портальных кранов обычно 6–62,5 м/мин, скорость передвижения по подкрановым путям — 20–60 м/мин. При интенсивной перевалке (много циклов, штучный или тарный груз) выгоднее кран с более высокими рабочими скоростями; при разовой операции с тяжеловесным грузом скорость вторична, важнее запас по грузоподъёмности на нужном вылете.'),
        ('Конструктивная особенность и типичная ошибка заказчиков', 'Портальный кран — это полноповоротный стреловой кран на самоходном П-образном основании (портале), которое передвигается по рельсовым подкрановым путям. Именно портал — сквозной проём в основании — и отличает его от гусеничных и автомобильных кранов: через него может проходить железнодорожный состав или колёсная техника, что и делает такие краны штатным решением для причалов, судостроительных верфей и гидротехнических объектов, где под краном идёт постоянный грузопоток.\n\nОтсюда и самая частая ошибка при заказе: портальный кран путают с мобильной техникой, которую можно просто «подать» на произвольную стройплощадку. На деле кран рельсовый — он либо уже стоит на путях конкретного объекта (порт, верфь, гидроузел), либо для его установки нужно заранее построить подкрановые пути под нужную колею и расчётную нагрузку на колесо (у портальных кранов это, как правило, 250–400 кН на колесо диаметром 560–710 мм, при 12 и более колёсах под каждой опорой, распределённых через балансирные тележки). Если путей на площадке нет, вопрос подбора крана превращается в вопрос проектирования и монтажа рельсового хозяйства — это отдельная задача, по срокам несопоставимая с арендой автокрана.'),
        ('Экономика: из чего складывается стоимость работы', 'Стоимость работы портального крана считается не так, как у автокрана «по звонку»: здесь почти никогда нет затрат на транспортировку самой машины к объекту — кран стационарный и закреплён за конкретным терминалом или площадкой. Цену формируют другие статьи: почасовая или посменная ставка работы крана с экипажем; тип и наличие нужной грузозахватной оснастки под конкретный груз (крюковая подвеска, грейфер под сыпучие грузы, спредер под контейнеры — это разное навесное оборудование, и его наличие на конкретной машине нужно уточнять отдельно); количество и длительность циклов подъёма за смену. Для площадок, где кран нужно устанавливать впервые, добавляются расходы на подготовку и приёмку подкрановых путей.\n\nСрок начала работ зависит в первую очередь от загрузки конкретного крана на терминале: в отличие от мобильной техники, свободную машину нельзя просто перебросить с соседнего объекта, если нужный кран уже занят другим заказом. Это стоит учитывать при планировании сроков перевалки заранее, а не за день до прихода судна или груза.'),
    ],
    'kran-balki-konsolnye-krany': [
        ('Как выбрать модель — не только по грузоподъёмности и пролёту', 'Грузоподъёмность и пролёт (для кран-балки) или вылет (для консольного крана) — только половина выбора. Вторая половина — режим работы механизма: насколько часто и с какой нагрузкой кран будет работать в смену. По ГОСТ 34017-2016, который соответствует международному ISO 4301, режим определяется классом использования (числом циклов подъёма за нормативный срок службы) и классом нагружения, а итоговая группа классификации механизма лежит в диапазоне от A1 (редкое включение, лёгкие нагрузки) до A8 (почти непрерывная работа с нагрузками, близкими к номинальным). Поставьте лёгкую электроталь на участок с постоянным цикличным конвейером — тормоза и механизм подъёма выработают ресурс в разы быстрее паспортного; обратная ситуация — переплата за тяжёлый режим там, где кран включается пару раз в смену. Поэтому в заявке стоит указывать не только вес груза, но и примерную частоту подъёмов.\n\nУ консольных кранов есть отдельный нюанс: у части моделей грузоподъёмность в паспорте указана именно для максимального вылета стрелы, а не как абсолютный максимум для любого положения груза — момент, который создаёт груз на конце стрелы, ограничен прочностью консоли, колонны или узла крепления к стене. При выборе стоит сразу зафиксировать расчётную пару «груз – вылет», а не подбирать оба параметра порознь «с запасом», иначе на практике кран не поднимет заявленный груз на нужном плече.'),
        ('Площадка и типичные ошибки при заказе', 'Чаще всего срок монтажа сдвигает не техника, а неготовность площадки: кран-балку или консольный кран нельзя просто «привезти и включить». Для опорной кран-балки нужны подкрановые пути с выверенной геометрией по всей длине — их укладка обычно идёт отдельным этапом, а не входит в поставку крана по умолчанию. Для подвесной — несущая способность перекрытия и шаг закладных под расчётную нагрузку. Для консольного крана на колонне — фундамент, рассчитанный на опрокидывающий момент от груза на максимальном вылете; для настенного — состояние стены и точка крепления на нужной высоте. Отдельно у консольных кранов нужно проверять запас по высоте помещения: крюк с поднятым грузом и дуга поворота стрелы должны укладываться в свободное пространство с учётом коммуникаций под потолком.\n\nТипичная ошибка заказчика — прислать только вес груза и «на глаз» размер помещения, без данных о том, готова ли площадка (проектная документация на закладные или фундамент, трёхфазное электропитание нужного номинала). Это не вопрос к технике, но именно это чаще всего откладывает монтаж на объекте на недели, а не сам подбор модели.'),
        ('Освидетельствование и что реально формирует цену', 'Кран-балка и консольный кран — не разовая поставка, а объект, который дальше стоит на техническом учёте. По федеральным нормам и правилам промышленной безопасности для подъёмных сооружений (приказ Ростехнадзора № 461) частичное техническое освидетельствование — по сути осмотр — проводится не реже одного раза в 12 месяцев, а полное, со статическими и динамическими испытаниями, — не реже одного раза в 3 года. Это стоит закладывать в план обслуживания сразу при покупке или долгосрочной аренде, а не откладывать до истечения срока: без пройденного освидетельствования эксплуатация крана незаконна.\n\nВ цену и срок поставки в этом сегменте закладывается не сама балка или консоль по отдельности, а комплект: несущая конструкция, электроталь, подкрановые пути или колонна, токоподвод, доставка, монтаж, пусконаладка и оформление документов на ввод в эксплуатацию. Поэтому итоговые цифры всегда зависят от того, стандартная это конфигурация «с полки» или пролёт/вылет вне стандартного ряда — под нестандартный типоразмер увеличивается и срок изготовления, и срок доставки.'),
    ],
    'zheleznodorozhnye-krany': [
        ('Как выбирать кран по грузоподъёмности и вылету, а не по паспортному тоннажу модели', 'У железнодорожных кранов, как и у любых стреловых кранов, грузоподъёмность — это не одно число, а грузовая характеристика: чем больше вылет стрелы от оси пути до точки подъёма груза, тем ниже допустимая масса груза, и разница между минимальным и максимальным вылетом может быть кратной. Поэтому заявка вида «нужен кран на столько-то тонн» сама по себе диспетчеру не помогает — важно назвать реальный вес груза и расстояние от оси пути (или от места стоянки крана) до точки подъёма и опускания. Если груз стоит в стороне от полотна, а не прямо у него, на большом вылете тот же кран физически может не поднять то, что легко берёт «под боком». Второй параметр подбора — группа режима работы: краны с механическим приводом делятся по интенсивности эксплуатации, от лёгкого режима до весьма тяжёлого. Разовый подъём при аварийно-восстановительных работах и постоянная циклическая погрузка на сортировочной станции — разные нагрузочные режимы, под которые нужна разная техника, даже если номинальная грузоподъёмность в паспорте совпадает.'),
        ('Привязка к путям и энергонезависимость — главное отличие от автокрана', 'Железнодорожный кран передвигается только по рельсам и не может, в отличие от автокрана, объехать препятствие или встать там, где удобнее: его положение всегда ограничено осью пути. Отсюда практика подачи — это не просто перегон, а согласованное включение в график движения: нужно получить технологическое окно у владельца инфраструктуры, будь то магистральные пути или подъездные пути предприятия, и сам перегон крана до объекта и обратно закладывается в срок отдельно от времени самой грузовой операции. Второй эксплуатационный момент — тип привода. Заметная часть парка кранов на ж/д ходу — дизель-электрические: у них собственная силовая установка, дизель приводит генератор, который питает механизмы крана, поэтому такой кран не зависит от контактной сети и может работать не только на станциях, но и на неэлектрифицированных участках, в полевых условиях. При выборе техники под задачу стоит уточнять именно это — способен ли конкретный кран работать автономно или требует внешнего электропитания.'),
        ('Из чего складывается срок и стоимость подачи крана', 'Типичная ошибка заказчика — считать, что оплачивается только время самой грузовой операции. На деле в срок и в цену закладываются: согласование окна с владельцем путей, перегон крана до объекта и обратно (нередко более долгий этап, чем сам подъём), при необходимости — переоснащение под тип груза, поскольку кран может работать крюком, грейфером для сыпучих грузов, электромагнитом для металлолома или спецзахватами под рельсы и шпалы, и смена навесного оборудования — это отдельная операция. Отдельная статья затрат — аттестованный машинист: ж/д кран относится к технике повышенной опасности и требует квалифицированного персонала, а не просто оператора. Играет роль и сезонность: доступность путей и очерёдность технологических окон меняются в периоды путевых и ремонтных работ, поэтому на загруженных направлениях согласование стоит планировать заранее, а не в день, когда груз уже нужно поднимать.'),
    ],
}
